WITH store_state_agg AS ( SELECT s.s_state, s.s_store_sk, s.s_store_name, AVG(sr.sr_net_loss) AS avg_store_net_loss FROM store s JOIN store_returns sr ON s.s_store_sk = sr.sr_store_sk GROUP BY s.s_state, s.s_store_sk, s.s_store_name ), state_total AS ( SELECT s_state, AVG(avg_store_net_loss) AS avg_state_net_loss FROM store_state_agg GROUP BY s_state ), web_total AS ( SELECT SUM(wr.wr_net_loss) AS total_web_net_loss FROM web_returns wr ) SELECT sa.s_state, sa.s_store_sk, sa.s_store_name, sa.avg_store_net_loss, st.avg_state_net_loss, (sa.avg_store_net_loss / NULLIF(st.avg_state_net_loss,0)) * 100 AS store_state_pct, CASE WHEN (sa.avg_store_net_loss / NULLIF(st.avg_state_net_loss,0)) * 100 > 10 THEN 'Key Store' ELSE 'Regular Store' END AS store_role, ROW_NUMBER() OVER (PARTITION BY sa.s_state ORDER BY sa.avg_store_net_loss DESC) AS store_rank_in_state, wt.total_web_net_loss FROM store_state_agg sa JOIN state_total st ON sa.s_state = st.s_state CROSS JOIN web_total wt ORDER BY sa.s_state, store_rank_in_state DESC LIMIT 40
